   407	/**
   408	 * @brief 按底部 toast 的实际字体宽度截断文本，并保留完整 UTF-8 字符。
   409	 * @param max_w     可用像素宽；非法/不完整序列截到上一个完整字符。
   410	 * @param max_bytes 可用字节数（不含结尾 NUL），避免超出 toast 缓冲区。
   411	 * @note  lv_text_get_width() 只声明在私有头 lv_text_private.h，且第 4 参是
   412	 *        lv_text_attributes_t*（非 letter_space）；这里改用公开的
   413	 *        lv_font_get_glyph_width() 逐字累加 adv_w（含 kerning），
   414	 *        与它 letter_space=0 时的算法一致。
   415	 */
   416	static size_t bicycle_ui_ctl_fit_utf8_width(const char * s, int32_t max_w,
   417	    size_t max_bytes)
   418	{
   419	    const lv_font_t * font = helm_font_sys(14, helm_font_title());
   420	    size_t n = 0u;
   421	    int32_t w = 0;
   422	
   423	    if (s == NULL || font == NULL || max_w <= 0) {
   424	        return 0u;
   425	    }
   426	
   427	    while (s[n] != '\0') {
   428	        const size_t len = bicycle_ui_ctl_utf8_len(s, n);
   429	        uint32_t cp;
   430	        uint32_t next = 0u;
   431	        size_t next_len;
   432	        int32_t adv;
   433	
   434	        if (len == 0u || n + len > max_bytes) {
   435	            break;
   436	        }
   437	
   438	        cp = bicycle_ui_ctl_utf8_cp(s + n, len);
   439	        next_len = bicycle_ui_ctl_utf8_len(s, n + len);
   440	        if (next_len != 0u) {
   441	            next = bicycle_ui_ctl_utf8_cp(s + n + len, next_len);
   442	        }
   443	
   444	        adv = (int32_t)lv_font_get_glyph_width(font, cp, next);
   445	        if (adv > max_w - w) {
   446	            break;
   447	        }
   448	
   449	        w += adv;
   450	        n += len;
   451	    }
   452	
   453	    return n;
   454	}
